//! Shared fixture loading for the criterion benches in this crate.
//!
//! The fixtures themselves live in the `concerto` repo, under
//! `migration/bench/fixtures/`, generated by
//! `migration/bench/generate-fixtures.mjs` (see that repo's
//! `migration/bench/README.md`). We read them from there rather than
//! duplicating a second copy in this repo, so both the TS harness
//! (`migration/bench/run-ts.mjs` in `concerto`) and this Rust harness load
//! byte-identical models.
//!
//! Per the migration plan's repo layout, `concerto` is checked out as a
//! sibling of this repo (e.g. both under `/home/user/`). Override the
//! location with the `CONCERTO_REPO` environment variable if that does not
//! hold for your checkout.

use std::path::PathBuf;

pub fn concerto_repo_dir() -> PathBuf {
    if let Ok(dir) = std::env::var("CONCERTO_REPO") {
        return PathBuf::from(dir);
    }
    // This crate lives at <workspace_root>/benches; the sibling repos
    // convention puts `concerto` next to the parent of the workspace root.
    let workspace_root = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("benches/ has a parent directory")
        .to_path_buf();
    let siblings_root = workspace_root
        .parent()
        .expect("the concerto-rust checkout has a parent directory");
    siblings_root.join("concerto")
}

pub fn fixtures_dir() -> PathBuf {
    concerto_repo_dir().join("migration/bench/fixtures")
}

/// Loads every `*.json` AST fixture from a model-set directory (see
/// `generate-fixtures.mjs`), sorted by file name for a deterministic order.
pub fn load_model_set(set_name: &str) -> Vec<(String, serde_json::Value)> {
    let dir = fixtures_dir().join("model-sets").join(set_name);
    let mut entries: Vec<_> = std::fs::read_dir(&dir)
        .unwrap_or_else(|e| panic!("reading fixture dir {}: {e}", dir.display()))
        .filter_map(|e| e.ok())
        .filter(|e| e.path().extension().and_then(|s| s.to_str()) == Some("json"))
        .collect();
    entries.sort_by_key(|e| e.file_name());

    entries
        .into_iter()
        .map(|e| {
            let path = e.path();
            let text = std::fs::read_to_string(&path)
                .unwrap_or_else(|err| panic!("reading {}: {err}", path.display()));
            let value: serde_json::Value = serde_json::from_str(&text)
                .unwrap_or_else(|err| panic!("parsing {}: {err}", path.display()));
            let name = path.file_name().unwrap().to_string_lossy().into_owned();
            (name, value)
        })
        .collect()
}
